 86→function HealthBanner({ health, loading, onVerify }: {
 87→  health: ResendHealth | null;
 88→  loading: boolean;
 89→  onVerify: () => void;
 90→}) {
 91→  if (loading) {
 92→    return (
 93→      <div className="rounded-lg border border-border bg-muted/30 p-4 flex items-center gap-3">
 94→        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
 95→        <span className="text-sm text-muted-foreground">Checking Resend connection...</span>
 96→      </div>
 97→    );
 98→  }
 99→
100→  if (!health) return null;
101→
102→  const issues: { icon: React.ElementType; text: string; severity: "error" | "warning" }[] = [];
103→
104→  if (!health.keyValid) {
105→    issues.push({ icon: XCircle, text: "API key is invalid or not configured", severity: "error" });
106→  }
107→  if (health.keyValid && !health.domainVerified) {
108→    issues.push({
109→      icon: AlertTriangle,
110→      text: `Domain for "${health.fromEmail}" is not verified in Resend. Emails will fail.`,
111→      severity: "warning",
112→    });
113→  }
114→
115→  if (issues.length === 0 && health.keyValid) {
116→    return (
117→      <div className="rounded-lg border border-green-200 bg-green-50 dark:border-green-900 dark:bg-green-950/50 p-4 space-y-2">
118→        <div className="flex items-center justify-between">
119→          <div className="flex items-center gap-2">
120→            <CheckCircle2 className="h-4 w-4 text-green-600" />
121→            <span className="text-sm font-medium text-green-700 dark:text-green-400">
122→              Resend Connected{health.domainName ? ` — ${health.domainName}` : ""}
123→            </span>
124→          </div>
125→          <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
126→            <RefreshCw className="h-3 w-3" /> Recheck
127→          </Button>
128→        </div>
129→        <div className="flex gap-3 text-xs text-green-600 dark:text-green-500">
130→          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> API key valid</span>
131→          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> Domain verified</span>
132→        </div>
133→      </div>
134→    );
135→  }
136→
137→  return (
138→    <div className="space-y-2">
139→      {issues.map((issue, i) => (
140→        <div
141→          key={i}
142→          className={`rounded-lg border p-3 flex items-start gap-2 ${
143→            issue.severity === "error"
144→              ? "border-destructive/50 bg-destructive/10 text-destructive"
145→              : "border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 text-amber-700 dark:text-amber-400"
146→          }`}
147→        >
148→          <issue.icon className="h-4 w-4 shrink-0 mt-0.5" />
149→          <p className="text-xs">{issue.text}</p>
150→        </div>
151→      ))}
152→      <div className="flex justify-end">
153→        <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
154→          <RefreshCw className="h-3 w-3" /> Recheck
155→        </Button>
156→      </div>
157→    </div>
158→  );
159→}
