  1→import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
  2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  3→
  4→const corsHeaders = {
  5→  "Access-Control-Allow-Origin": "*",
  6→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  7→};
  8→
  9→serve(async (req) => {
 10→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 11→
 12→  try {
 13→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 14→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 15→    const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
 16→
 17→    const authHeader = req.headers.get("Authorization");
 18→    if (!authHeader) throw new Error("No auth");
 19→
 20→    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
 21→      global: { headers: { Authorization: authHeader } },
 22→    });
 23→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
 24→    if (userError || !user) throw new Error("Unauthorized");
 25→    const userId = user.id;
 26→
 27→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 28→
 29→    const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", userId);
 30→    if (!roles?.some((r: any) => r.role === "admin")) {
 31→      return new Response(JSON.stringify({ error: "Admin access required" }), {
 32→        status: 403, headers: { ...corsHeaders, "Content-Type": "application/json" },
 33→      });
 34→    }
 35→
 36→    const body = await req.json();
 37→    const { key_name } = body;
 38→
 39→    // ─── DNS MX record check ───
 40→    if (key_name === "DNS_MX_CHECK") {
 41→      const domain = body.domain;
 42→      if (!domain) throw new Error("Missing domain");
 43→
 44→      try {
 45→        // Use Google DNS-over-HTTPS API to check MX records
 46→        const dnsRes = await fetch(`https://dns.google/resolve?name=${encodeURIComponent(domain)}&type=MX`);
 47→        const dnsData = await dnsRes.json();
 48→
 49→        const mxRecords: { exchange: string; priority: number }[] = [];
 50→        let pointsToExpected = false;
 51→
 52→        if (dnsData.Answer && Array.isArray(dnsData.Answer)) {
 53→          for (const answer of dnsData.Answer) {
 54→            if (answer.type === 15) { // MX record type
 55→              const parts = answer.data.split(" ");
 56→              const priority = parseInt(parts[0], 10);
 57→              const exchange = (parts[1] || "").replace(/\.$/, "").toLowerCase();
 58→              mxRecords.push({ exchange, priority });
 59→              // Accept any valid MX record pointing to a known email provider
 60→              if (exchange.includes("inbound.postmarkapp.com") || exchange.includes("resend") || exchange.includes("mx")) {
 61→                pointsToExpected = true;
 62→              }
 63→            }
 64→          }
 65→        }
 66→
 67→        return new Response(JSON.stringify({
 68→          status: mxRecords.length > 0 ? "success" : "no_records",
 69→          domain,
 70→          mx_records: mxRecords,
 71→          points_to_expected: pointsToExpected,
 72→        }), {
 73→          headers: { ...corsHeaders, "Content-Type": "application/json" },
 74→        });
 75→      } catch (e: unknown) {
 76→        return new Response(JSON.stringify({
 77→          status: "error",
 78→          error: e instanceof Error ? e.message : String(e),
 79→        }), {
 80→          headers: { ...corsHeaders, "Content-Type": "application/json" },
 81→        });
 82→      }
 83→    }
 84→
 85→    if (!key_name) throw new Error("Missing key_name");
 86→
 87→    let status = "failed";
 88→    let errorMsg = "";
 89→    let details: Record<string, any> = {};
 90→
 91→    if (key_name === "OPENAI_API_KEY") {
 92→      const openaiKey = Deno.env.get("OPENAI_API_KEY");
 93→      if (!openaiKey) {
 94→        errorMsg = "OPENAI_API_KEY secret is not configured";
 95→      } else {
 96→        try {
 97→          const res = await fetch("https://api.openai.com/v1/models", {
 98→            headers: { Authorization: `Bearer ${openaiKey}` },
 99→          });
100→          if (res.ok) {
101→            status = "success";
102→          } else {
103→            const body = await res.text();
104→            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
105→          }
106→        } catch (e: unknown) {
107→          errorMsg = e instanceof Error ? e.message : String(e);
108→        }
109→      }
110→    } else if (key_name === "RAZORPAY_KEY_ID") {
111→      const razorpayKeyId = Deno.env.get("RAZORPAY_KEY_ID");
112→      const razorpayKeySecret = Deno.env.get("RAZORPAY_KEY_SECRET");
113→      if (!razorpayKeyId || !razorpayKeySecret) {
114→        errorMsg = "RAZORPAY_KEY_ID or RAZORPAY_KEY_SECRET secret is not configured";
115→      } else {
116→        try {
117→          const res = await fetch("https://api.razorpay.com/v1/payments?count=1", {
118→            headers: {
119→              Authorization: "Basic " + btoa(`${razorpayKeyId}:${razorpayKeySecret}`),
120→            },
121→          });
122→          if (res.ok) {
123→            status = "success";
124→          } else {
125→            const body = await res.text();
126→            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
127→          }
128→        } catch (e: unknown) {
129→          errorMsg = e instanceof Error ? e.message : String(e);
130→        }
131→      }
132→    } else if (key_name === "RESEND_API_KEY") {
133→      // Read API key from platform_config (stored in DB, not env vars)
134→      const { data: config } = await supabase
135→        .from("platform_config")
136→        .select("resend_api_key, email_from_address")
137→        .limit(1)
138→        .single();
139→
140→      const apiKey = config?.resend_api_key;
141→      if (!apiKey) {
142→        errorMsg = "Resend API key is not configured. Add it in Email Settings.";
143→      } else {
144→        try {
145→          // Validate API key by listing domains
146→          const domainsRes = await fetch("https://api.resend.com/domains", {
147→            headers: {
148→              "Authorization": `Bearer ${apiKey}`,
149→              "Content-Type": "application/json",
150→            },
151→          });
152→          const domainsBody = await domainsRes.text();
153→
154→          if (!domainsRes.ok) {
155→            errorMsg = `Invalid API key (${domainsRes.status})`;
156→            details.keyValid = false;
157→          } else {
158→            details.keyValid = true;
159→
160→            try {
161→              const domainsData = JSON.parse(domainsBody);
162→              const domains = domainsData.data || [];
163→              details.totalDomains = domains.length;
164→
165→              // Check if from address domain is verified
166→              const fromEmail = config?.email_from_address || "noreply@rankora.co";
167→              details.fromEmail = fromEmail;
168→              const fromDomain = fromEmail.split("@")[1]?.toLowerCase();
169→
170→              const domainMatch = domains.find((d: any) =>
171→                d.name?.toLowerCase() === fromDomain
172→              );
173→
174→              if (domainMatch) {
175→                details.domainVerified = domainMatch.status === "verified";
176→                details.domainName = domainMatch.name || "";
177→              } else {
178→                details.domainVerified = false;
179→                details.domainName = "";
180→              }
181→            } catch { details.domainVerified = false; }
182→
183→            status = "success";
184→          }
185→        } catch (e: unknown) {
186→          errorMsg = e instanceof Error ? e.message : String(e);
187→        }
188→      }
189→    } else if (key_name === "GEMINI_API_KEY") {
190→      const geminiKey = Deno.env.get("GEMINI_API_KEY");
191→      if (!geminiKey) {
192→        errorMsg = "GEMINI_API_KEY secret is not configured";
193→      } else {
194→        try {
195→          const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${geminiKey}`);
196→          if (res.ok) {
197→            status = "success";
198→            const body = await res.json();
199→            details.modelsCount = body.models?.length || 0;
200→          } else {
201→            const body = await res.text();
202→            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
203→          }
204→        } catch (e: unknown) {
205→          errorMsg = e instanceof Error ? e.message : String(e);
206→        }
207→      }
208→    } else if (key_name === "DODO_PAYMENTS_API_KEY") {
209→      const dodoKey = Deno.env.get("DODO_PAYMENTS_API_KEY");
210→      if (!dodoKey) {
211→        errorMsg = "DODO_PAYMENTS_API_KEY secret is not configured";
212→      } else {
213→        try {
214→          // Read environment from platform_config (UI-editable) or fall back to env var
215→          const { data: cfg } = await supabase
216→            .from("platform_config")
217→            .select("dodo_payments_environment")
218→            .limit(1)
219→            .single();
220→          const dodoEnv = (cfg as any)?.dodo_payments_environment
