227→          const res = await fetch(`${dodoBaseUrl}/payments?page_size=1`, {
228→            headers: { Authorization: `Bearer ${dodoKey}` },
229→          });
230→          if (res.ok) {
231→            status = "success";
232→            details.environment = dodoEnv;
233→          } else {
234→            const body = await res.text();
235→            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
236→          }
237→        } catch (e: unknown) {
238→          errorMsg = e instanceof Error ? e.message : String(e);
239→        }
240→      }
241→    } else {
242→      errorMsg = `Unknown integration: ${key_name}`;
243→    }
244→
245→    // Update integrations table
246→    await supabase.from("integrations").update({
247→      last_tested_at: new Date().toISOString(),
248→      last_test_status: status,
249→      is_configured: status === "success",
250→    }).eq("key_name", key_name);
251→
252→    return new Response(JSON.stringify({ status, error: errorMsg || undefined, details }), {
253→      headers: { ...corsHeaders, "Content-Type": "application/json" },
254→    });
255→  } catch (err: unknown) {
256→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
257→      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
258→    });
259→  }
260→});
